SELECT AVG(value) AS avg_temperature, PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY value) AS q1, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY value) AS q3, COUNT(DISTINCT microevent_id) AS microevent_count, SUM(CASE WHEN itemid = 258077 THEN 1 ELSE 0 END) AS mi_count FROM labevents JOIN icustays ON labevents.subject_id = icustays.subject_id AND labevents.hadm_id = icustays.hadm_id JOIN patients ON icustays.subject_id = patients.subject_id AND icustays.hadm_id = patients.hadm_id WHERE patients.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, patients.dob)) = 76 AND EXTRACT(YEAR FROM icustays.intime) BETWEEN 2019 AND 2020 AND value_uom = '°C' AND (itemid = 258077 OR itemid = 258078) AND (charttime BETWEEN intime AND (intime + interval '48 hours'));